    def proc_update_task_notify(self, type, msg):
        if type == "status":
            self.statusbar.showMessage(msg[0])
        elif type == "check_download":
            self.statusbar.showMessage(msg[0])
            reply = QtWidgets.QMessageBox.question(
                self,
                'download_new_version',
                '[updater]:Find a new version, start silent download and upgrade? ',
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.Yes
            )

            if reply == QtWidgets.QMessageBox.Yes:
                self.notify_update_signal.emit("download")
                self.statusbar.showMessage("[updater]:Preparing for download...")
            else:
                self.notify_update_signal.emit("no_download")
                self.statusbar.showMessage("[updater]:Cancel download, will remind you later")
        elif type == "restart_update":
            self.statusbar.showMessage("[updater]:download completed, strongly recommend that you restart to complete the upgrade for a better experience")
            reply = QtWidgets.QMessageBox.question(
                self,
                'restart_update',
                'Download package completed, We strongly recommend that you restart to complete the upgrade',
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.Yes
            )

            if reply == QtWidgets.QMessageBox.Yes:
                self.statusbar.showMessage("[updater]:Start restarting, please wait, we will automatically upgrade for you")
                import subprocess
                import time
                time.sleep(1)
                QLLogging.log.debug(f"execute \"{msg}\"")
                subprocess.Popen(msg, shell = False)  # 不使用 shell=True，避免潜在的安全风险

                self.do_exit_application()
            else:
                self.statusbar.showMessage("[updater]:Cancel update, will remind you later")

    def set_update_task_signal(self, signal):
        signal.connect(self.proc_update_task_notify)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():  # 检查是否包含URLs（文件路径）
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.setDropAction(Qt.CopyAction)
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        if event.mimeData().hasUrls():
            event.setDropAction(Qt.CopyAction)
            event.accept()

            # 获取所有拖放的文件路径
            file_paths = [url.toLocalFile() for url in event.mimeData().urls()]
            for path in file_paths:
                # 在这里你可以添加上传逻辑，现在仅打印文件路径
                print(f"Dragged file: {path}")
                item = QListWidgetItem(path)
                self.addItem(item)
        else:
            event.ignore()

