    def open_data_import(self):
        self.browse_files()

    def browse_files(self):
        from PyQt5.QtCore import QSettings
        self.settings = QSettings("QUANLAN", "AR_analyser")
        self.last_opened_path = self.settings.value("lastOpenedPath", "")

        options = QFileDialog.Options()
        file_filter = 'EDF and BDF Files (*.edf *.bdf)'
        file_name, _ = QFileDialog.getOpenFileName(None, "Select EDF or BDF File", self.last_opened_path,
                                                   options=options, filter=file_filter)
        if file_name:
            self.file_path = file_name
            self.settings.setValue("lastOpenedPath", os.path.dirname(file_name))
            self.process_path()
            self.textEdit.show()
            self.welcome_text.hide()
            self.welcome_text0.hide()
            self.browse_button.hide()
            self.welcome_text1.hide()
        OPLog.write(SQLLiteDB_Only_MainTread.user_db, OPType.BASIC.value, 'browse files', 0)

    def process_path(self):
        if self.file_path.endswith('.edf') or self.file_path.endswith('.bdf'):
            try:
                self.showInfo(self.file_path)

                base_path = os.path.dirname(self.file_path)
                result_path = os.path.join(base_path, 'Result')
                from datetime import datetime
                folder_name = datetime.now().strftime('%Y%m%d_%H%M%S')
                folder_path = os.path.join(result_path, folder_name)
                os.makedirs(result_path, exist_ok=True)
                os.makedirs(folder_path, exist_ok=True)
                self.updateDescription(folder_path)
                QLLogging.log.info(f"process file {self.file_path} successfully")
            except Exception as e:
                QLLogging.log.exception(f"Failed to load the file: {e}")


        else:
            QMessageBox.critical(None, "File Error",
                                 "The selected file is not a .edf file. Please select a valid .edf file.")

